export interface Frontmatter {
  title: string;
  date?: string;
  tags?: string[];
  draft?: boolean;
}

export interface Post {
  frontmatter: Frontmatter;
  content: string;
  html: string;
  slug: string;
  url: string;
  description: string;
}

export interface SiteConfig {
  title: string;
  description: string;
  url: string;
}

export interface BuildOptions {
  source: string;
  templates: string;
  output: string;
  title?: string;
  description?: string;
  url?: string;
  includeDrafts?: boolean;
}

export interface ServeOptions extends BuildOptions {
  port: string;
}

import { readFile } from 'fs/promises';
import { basename, extname } from 'path';
import matter from 'gray-matter';
import { HighlightJS } from 'highlight.js';
import { Frontmatter, Post } from './types.js';

export function slugify(filename: string): string {
  return basename(filename, extname(filename))
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');
}

export function parseFrontmatter(raw: string, filename: string): {
  frontmatter: Frontmatter;
  content: string;
} {
  const parsed = matter(raw);
  const fm = parsed.data as Record<string, unknown>;
  return {
    frontmatter: {
      title: (fm.title as string) || slugify(filename),
      date: fm.date as string | undefined,
      tags: Array.isArray(fm.tags) ? fm.tags.map(String) : undefined,
      draft: fm.draft === true || fm.draft === 'true',
    },
    content: parsed.content,
  };
}

export async function readPost(filepath: string): Promise<Post> {
  const raw = await readFile(filepath, 'utf-8');
  const { frontmatter, content } = parseFrontmatter(raw, filepath);
  const slug = slugify(filepath);
  return {
    frontmatter,
    content,
    html: '', // populated later by renderer
    slug,
    url: `/${slug}/`,
    description: content.slice(0, 200).replace(/\n/g, ' ').trim(),
  };
}

import hljs from 'highlight.js';
import { marked } from 'marked';

export function setupMarked(): void {
  marked.setOptions({
    async: false,
  });
}

export function markdownToHtml(markdown: string): string {
  return marked.parse(markdown) as string;
}

export function highlightCode(html: string): string {
  return html.replace(
    /<pre><code(?:\s+class="language-([^"]*)")?>([\s\S]*?)<\/code><\/pre>/g,
    (_match, lang, code) => {
      const decoded = code
        .replace(/&lt;/g, '<')
        .replace(/&gt;/g, '>')
        .replace(/&amp;/g, '&')
        .replace(/&quot;/g, '"');
      const language = lang && hljs.getLanguage(lang) ? lang : 'plaintext';
      const highlighted = hljs.highlight(decoded, { language }).value;
      return `<pre><code class="hljs language-${language}">${highlighted}</code></pre>`;
    },
  );
}

