import { readFile } from 'fs/promises';
import { join, extname } from 'path';
import { readdirSync } from 'fs';
import Handlebars from 'handlebars';
import { Post, SiteConfig } from './types.js';

export interface TemplateEngine {
  render(template: string, context: Record<string, unknown>): string;
}

export async function loadTemplates(
  templatesDir: string,
): Promise<{ templates: Map<string, HandlebarsTemplateFunction>; layout: HandlebarsTemplateFunction | null }> {
  const templates = new Map<string, HandlebarsTemplateFunction>();
  let layout: HandlebarsTemplateFunction | null = null;

  const partialsDir = join(templatesDir, 'partials');
  try {
    const partialFiles = readdirSync(partialsDir);
    for (const file of partialFiles) {
      if (extname(file) === '.hbs') {
        const content = await readFile(join(partialsDir, file), 'utf-8');
        const name = file.replace('.hbs', '');
        Handlebars.registerPartial(name, content);
      }
    }
  } catch {
    // no partials directory, ignore
  }

  const entries = readdirSync(templatesDir);
  for (const file of entries) {
    if (extname(file) !== '.hbs') continue;
    const content = await readFile(join(templatesDir, file), 'utf-8');
    const compiled = Handlebars.compile(content);
    const name = file.replace('.hbs', '');
    if (name === 'layout') {
      layout = compiled;
    } else {
      templates.set(name, compiled);
    }
  }

  return { templates, layout };
}

export function registerHelpers(site: SiteConfig): void {
  Handlebars.registerHelper('dateFormat', function (date: string) {
    if (!date) return '';
    const d = new Date(date);
    return d.toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
    });
  });

  Handlebars.registerHelper('rssDate', function (date: string) {
    if (!date) return '';
    return new Date(date).toUTCString();
  });

  Handlebars.registerHelper('tagUrl', function (tag: string) {
    return `/tags/${encodeURIComponent(tag.toLowerCase().replace(/\s+/g, '-'))}/`;
  });

  Handlebars.registerHelper('isoDate', function (date: string) {
    if (!date) return '';
    return new Date(date).toISOString();
  });
}

export interface RenderContext {
  site: SiteConfig;
  posts?: Post[];
  post?: Post;
  tag?: string;
  body?: string;
  title?: string;
}

export function renderPage(
  templates: Map<string, HandlebarsTemplateFunction>,
  layout: HandlebarsTemplateFunction | null,
  templateName: string,
  context: RenderContext,
): string {
  const tpl = templates.get(templateName);
  if (!tpl) {
    throw new Error(`Template "${templateName}" not found`);
  }

  const pageHtml = tpl(context);

  if (layout && templateName !== 'rss') {
    return layout({ ...context, body: pageHtml });
  }

  return pageHtml;
}

import { readFile } from 'fs/promises';
import { join, extname } from 'path';
import { readdirSync } from 'fs';
import Handlebars from 'handlebars';
import { Post, SiteConfig } from './types.js';

type CompiledTemplate = (context: Record<string, unknown>) => string;

export async function loadTemplates(
  templatesDir: string,
): Promise<{ templates: Map<string, CompiledTemplate>; layout: CompiledTemplate | null }> {
  const templates = new Map<string, CompiledTemplate>();
  let layout: CompiledTemplate | null = null;

  const partialsDir = join(templatesDir, 'partials');
  try {
    const partialFiles = readdirSync(partialsDir);
    for (const file of partialFiles) {
      if (extname(file) === '.hbs') {
        const content = await readFile(join(partialsDir, file), 'utf-8');
        const name = file.replace('.hbs', '');
        Handlebars.registerPartial(name, content);
      }
    }
  } catch {
    // no partials directory, ignore
  }

  const entries = readdirSync(templatesDir);
  for (const file of entries) {
    if (extname(file) !== '.hbs') continue;
    const content = await readFile(join(templatesDir, file), 'utf-8');
    const compiled = Handlebars.compile(content) as CompiledTemplate;
    const name = file.replace('.hbs', '');
    if (name === 'layout') {
      layout = compiled;
    } else {
      templates.set(name, compiled);
    }
  }

  return { templates, layout };
}

export function registerHelpers(site: SiteConfig): void {
  Handlebars.registerHelper('dateFormat', function (date: string) {
    if (!date) return '';
    const d = new Date(date);
    return d.toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
    });
  });

  Handlebars.registerHelper('rssDate', function (date: string) {
    if (!date) return '';
    return new Date(date).toUTCString();
  });

  Handlebars.registerHelper('tagUrl', function (tag: string) {
    return `/tags/${encodeURIComponent(tag.toLowerCase().replace(/\s+/g, '-'))}/`;
  });

  Handlebars.registerHelper('isoDate', function (date: string) {
    if (!date) return '';
    return new Date(date).toISOString();
  });
}

export interface RenderContext {
  site: SiteConfig;
  posts?: Post[];
  post?: Post;
  tag?: string;
  body?: string;
  title?: string;
  content?: string;
  date?: string;
  tags?: string[];
  url?: string;
  description?: string;
}

export function renderPage(
  templates: Map<string, CompiledTemplate>,
  layout: CompiledTemplate | null,
  templateName: string,
  context: RenderContext,
): string {
  const tpl = templates.get(templateName);
  if (!tpl) {
    throw new Error(`Template "${templateName}" not found`);
  }

  const pageHtml = tpl(context as Record<string, unknown>);

  if (layout && templateName !== 'rss') {
    return layout({ ...context, body: pageHtml } as Record<string, unknown>);
  }

  return pageHtml;
}

import { readFile, writeFile, mkdir, readdir } from 'fs/promises';
import { join, extname } from 'path';
import { existsSync, statSync } from 'fs';
import { globSync } from 'fs';
import { readPost } from './frontmatter.js';
import { loadTemplates, registerHelpers, renderPage } from './renderer.js';
import { markdownToHtml, highlightCode, setupMarked } from './highlight.js';
import { BuildOptions, Post, SiteConfig } from './types.js';

async function findMarkdownFiles(dir: string): Promise<string[]> {
  const results: string[] = [];
  async function walk(current: string) {
    const entries = await readdir(current, { withFileTypes: true });
    for (const entry of entries) {
      const fullPath = join(current, entry.name);
      if (entry.isDirectory()) {
        await walk(fullPath);
      } else if (extname(entry.name) === '.md') {
        results.push(fullPath);
      }
    }
  }
  await walk(dir);
  return results;
}

async function loadSiteConfig(
  sourceDir: string,
  options: BuildOptions,
): Promise<SiteConfig> {
  const configPath = join(sourceDir, 'site.json');
  let fileConfig: Partial<SiteConfig> = {};
  try {
    const raw = await readFile(configPath, 'utf-8');
    fileConfig = JSON.parse(raw);
  } catch {
    // no site.json, use defaults
  }

  return {
    title: options.title || fileConfig.title || 'My Site',
    description: options.description || fileConfig.description || '',
    url: options.url || fileConfig.url || 'http://localhost:3000',
  };
}

export async function build(options: BuildOptions): Promise<void> {
  setupMarked();
  const site = await loadSiteConfig(options.source, options);
  registerHelpers(site);

  await mkdir(options.output, { recursive: true });

  const mdFiles = await findMarkdownFiles(options.source);

  let posts: Post[] = [];
  for (const filepath of mdFiles) {
    const post = await readPost(filepath);
    posts.push(post);
  }

  if (!options.includeDrafts) {
    posts = posts.filter((p) => !p.frontmatter.draft);
  }

  posts.sort((a, b) => {
    const da = a.frontmatter.date ? new Date(a.frontmatter.date).getTime() : 0;
    const db = b.frontmatter.date ? new Date(b.frontmatter.date).getTime() : 0;
    return db - da;
  });

  for (const post of posts) {
    const rawHtml = markdownToHtml(post.content);
    post.html = highlightCode(rawHtml);
  }

  const { templates, layout } = await loadTemplates(options.templates);

  for (const post of posts) {
    const postDir = join(options.output, post.slug);
    await mkdir(postDir, { recursive: true });

    const html = renderPage(templates, layout, 'post', {
      site,
      post,
      title: post.frontmatter.title,
      content: post.html,
      date: post.frontmatter.date,
      tags: post.frontmatter.tags,
      url: post.url,
      description: post.description,
      posts,
    });

    await writeFile(join(postDir, 'index.html'), html);
  }

  const allTags = new Map<string, Post[]>();
  for (const post of posts) {
    if (post.frontmatter.tags) {
      for (const tag of post.frontmatter.tags) {
        if (!allTags.has(tag)) allTags.set(tag, []);
        allTags.get(tag)!.push(post);
      }
    }
  }

  for (const [tag, taggedPosts] of allTags) {
    const tagSlug = tag.toLowerCase().replace(/\s+/g, '-');
    const tagDir = join(options.output, 'tags', tagSlug);
    await mkdir(tagDir, { recursive: true });

    const html = renderPage(templates, layout, 'tag', {
      site,
      tag,
      posts: taggedPosts,
      title: `Tag: ${tag}`,
    });

    await writeFile(join(tagDir, 'index.html'), html);
  }

  if (templates.has('index')) {
    const html = renderPage(templates, layout, 'index', {
      site,
      posts,
      title: site.title,
    });
    await writeFile(join(options.output, 'index.html'), html);
  }

  if (templates.has('rss')) {
    const rssXml = renderPage(templates, layout, 'rss', {
      site,
      posts,
      title: site.title,
    });
    await writeFile(join(options.output, 'feed.xml'), rssXml);
  }
}

